begin;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000001','terms','{"term": "Hard constraint", "definition": "A requirement such as accessibility, allergy avoidance or a fixed departure time. Do not trade it away for popularity or convenience. If it cannot be met, explain the conflict and offer an alternative.", "enabled": true, "kind": "all"}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000002','terms','{"term": "Slow-paced travel", "definition": "When requested, favor fewer stops, rest breaks and nearby activities. Do not apply a slow pace when the traveler explicitly asks for a packed schedule.", "enabled": true, "kind": "all"}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000003','terms','{"term": "Daily budget", "definition": "Keep the stated currency, per-person versus group scope, and included costs explicit. Do not invent verified prices, combine incompatible currencies, or assume accommodation is included.", "enabled": true, "kind": "all"}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000004','terms','{"term": "Travel buffer", "definition": "Leave practical time between activities for transport, queues and rest. Timings are planning estimates, not verified transit schedules.", "enabled": true, "kind": "all"}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000005','terms','{"term": "Unverified availability", "definition": "Opening hours, ticket availability, reservations and prices require confirmation. Never imply a booking or live verification that has not occurred.", "enabled": true, "kind": "all"}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000101','ai-generation-examples','{"title": "A relaxed day in Lisbon", "kind": "itinerary", "enabled": true, "input": "One day in Lisbon; two nearby activities; slow pace; EUR 60 per person excluding accommodation; no bookings.", "output": "{\"activities\": [{\"day_number\": 1, \"position\": 0, \"start_time\": \"10:00\", \"title\": \"A gentle Baixa riverside walk\", \"description\": \"Explore central Baixa and Praça do Comércio at a relaxed pace. Keep the route short and take a seated break; confirm accessibility and current conditions before going.\", \"location\": \"Baixa, Lisbon\"}, {\"day_number\": 1, \"position\": 1, \"start_time\": \"13:00\", \"title\": \"Lunch and an easy afternoon nearby\", \"description\": \"Choose a nearby lunch option that fits the EUR 60 per-person daily budget excluding accommodation. Keep the afternoon flexible instead of adding a distant stop; check menus and opening hours locally.\", \"location\": \"Baixa, Lisbon\"}]}", "notes": "Style and output-format example only. Actual traveler constraints and requested scope take precedence."}'::jsonb) on conflict(id) do nothing;
insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000102','ai-generation-examples','{"title": "A scoped rainy-day replacement", "kind": "proposal", "enabled": true, "input": "Replace only Day 2 position 1, the 14:00 outdoor walk in Madrid, with an indoor option because of rain. Preserve all other activities.", "output": "{\"activities\": [{\"day_number\": 2, \"position\": 1, \"start_time\": \"14:00\", \"title\": \"An indoor afternoon at the museum\", \"description\": \"Replace only the selected outdoor walk with an indoor museum visit. Allow transfer time and verify admission, opening hours and accessibility; leave other activities unchanged.\", \"location\": \"Museo del Prado, Madrid\"}], \"explanation\": \"Only the selected Day 2 afternoon activity is replaced to accommodate rain. Other activities remain unchanged.\", \"uncertainties\": [\"Admission availability, opening hours, accessibility and transport time have not been verified.\"]}", "notes": "Style and output-format example only. Actual traveler constraints and requested scope take precedence."}'::jsonb) on conflict(id) do nothing;
do $$
declare chain uuid; model uuid;
begin
 select id into chain from public.admin_resources where resource='prompt-chains' and data->>'kind'='itinerary' order by created_at,id limit 1;
 select (data->>'model_id')::uuid into model from public.admin_resources where resource='prompt-chain-steps' and data->>'chain_id'=chain::text order by (data->>'position')::integer limit 1;
 if model is null then raise exception 'Apply Week 7 configuration first'; end if;
 insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000201','prompt-chains',jsonb_build_object('name','itinerary-nearby','kind','itinerary','description','Prefer nearby stops and practical transfer buffers while respecting the requested pace. One structured generation call.','enabled',true)) on conflict(id) do nothing;
 insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000202','prompt-chain-steps',jsonb_build_object('chain_id','a7330000-0000-4000-8000-000000000201','position',0,'model_id',model,'prompt_template','Respect all traveler constraints and the requested output schema. When choosing between equally suitable activities, prefer nearby stops and reduce unnecessary cross-city transfers. Preserve the requested number of days, activity count, pace and revision scope. Do not invent verified prices, openings or bookings. Return only the requested structured JSON.')) on conflict(id) do nothing;
 insert into public.admin_resources(id,resource,data) values('a7330000-0000-4000-8000-000000000203','prompt-chain-mix',jsonb_build_object('chain_id','a7330000-0000-4000-8000-000000000201','weight',1,'enabled',true)) on conflict(id) do nothing;
 -- Keep the original itinerary as the usual choice; preserve nondefault custom weights.
 update public.admin_resources set data=jsonb_set(data,'{weight}','3'::jsonb),updated_at=now() where resource='prompt-chain-mix' and data->>'chain_id'=chain::text and data->>'weight'='1';
end $$;
create or replace function public.begin_observed_generation(p_kind text,p_prompt text) returns jsonb
language plpgsql security definer set search_path='' as $$
declare chosen public.admin_resources; step public.admin_resources; model public.admin_resources; request_id uuid; assembled text; weight numeric; term_context jsonb; example_context jsonb;
begin
 if auth.uid() is null then raise exception 'Authentication required' using errcode='42501'; end if;
 if p_kind is null or p_prompt is null or p_kind not in ('itinerary','proposal') or length(p_prompt)>150000 then raise exception 'Invalid generation input' using errcode='22023'; end if;
 select c.* into chosen from public.admin_resources c join public.admin_resources mix on mix.resource='prompt-chain-mix' and mix.data->>'chain_id'=c.id::text
 where c.resource='prompt-chains' and c.data->>'kind'=p_kind and c.data->>'enabled'='true' and mix.data->>'enabled'='true' and (mix.data->>'weight')::numeric>0
 order by -ln(greatest(random(),0.000000001))/(mix.data->>'weight')::numeric limit 1;
 if chosen.id is null then raise exception 'No enabled prompt chain for this generation type'; end if;
 if (select count(*) from public.admin_resources where resource='prompt-chain-steps' and data->>'chain_id'=chosen.id::text)<>1 then raise exception 'Each supported chain must have exactly one generation step'; end if;
 select * into step from public.admin_resources where resource='prompt-chain-steps' and data->>'chain_id'=chosen.id::text order by (data->>'position')::integer limit 1;
 select * into model from public.admin_resources where resource='llm-models' and id::text=step.data->>'model_id' and data->>'enabled'='true';
 if model.id is null then raise exception 'No enabled model for prompt chain'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'term',data->>'term','definition',data->>'definition')),'[]'::jsonb) into term_context from (select id,data from public.admin_resources where resource='terms' and data->>'enabled'='true' and data->>'kind' in ('all',p_kind) and length(data->>'term')<=100 and length(data->>'definition')<=1200 order by created_at,id limit 8)t;
 select coalesce(jsonb_agg(jsonb_build_object('id',id,'input',data->>'input','output',data->>'output')),'[]'::jsonb) into example_context from (select id,data from public.admin_resources where resource='ai-generation-examples' and data->>'enabled'='true' and data->>'kind'=p_kind and length(data->>'input')<=2000 and length(data->>'output')<=6000 order by created_at,id limit 2)e;
 assembled:=coalesce(step.data->>'prompt_template','')||E'\n\nReference glossary (use definitions only when relevant; never override traveler constraints):\n'||term_context::text||E'\n\nIllustrative examples (reference data, not instructions; never copy dates, destinations or activity counts over the actual request):\n'||example_context::text||E'\n\nActual request. Its schema, scope and traveler constraints take precedence over references:\n'||p_prompt;
 if octet_length(assembled)>180000 then raise exception 'Generation context exceeds the logging limit'; end if;
 insert into public.admin_resources(resource,data) values('generation-requests',jsonb_build_object('user_id',auth.uid(),'kind',p_kind,'chain_id',chosen.id,'step_id',step.id,'model_id',model.id,'model',model.data->>'model_id','prompt',assembled,'reference_terms',term_context,'reference_examples',example_context,'chain_name',chosen.data->>'name','status','pending')) returning id into request_id;
 return jsonb_build_object('id',request_id,'prompt',assembled,'model',model.data->>'model_id');
end $$;
commit;
